import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs/promises';import os from 'node:os';import {join} from 'node:path';
import {DatabaseSync} from 'node:sqlite';
import {ProbeBroker} from '../src/broker.mjs';import {processRun,liveGroupMembers} from '../src/process.mjs';
const delay=ms=>new Promise(r=>setTimeout(r,ms));
async function fixture(extra={}){
 const root=await fs.mkdtemp(join(os.tmpdir(),'fix1-life-')),events=new Map(),sent=[];const now=Date.now();let calls=0;
 const config={file:join(root,'broker.sqlite'),appId:'a',tenantId:'t',participants:[{id:'u',alias:'A'}],deadline:now+60000,verifyTimeoutMs:30,sendTimeoutMs:30,readbackTimeoutMs:30,maxStopMs:2500,
  verify:async id=>events.get(id),execute:async x=>{calls++;return {marker:x.marker,summary:'synthetic'}},reply:async(t,text)=>{const r={messageId:'r'+sent.length,chatId:t.chatId,text};sent.push(r);return r;},readReply:async id=>sent.find(x=>x.messageId===id),...extra};
 if(!config.execute.processLifecycle)config.execute.processLifecycle='logical-only'; // deterministic in-process fixture; real process-manager receipts still take precedence
 let broker=new ProbeBroker(config);
 const accept=(text,id)=>{const e={appId:'a',tenantId:'t',senderId:'u',senderType:'user',chatId:'c',chatType:'p2p',messageId:id,text,createdAt:Date.now()};events.set(id,e);return broker.accept(e);};
 return {root,config,events,sent,accept,get broker(){return broker;},get calls(){return calls;},async restart(){await broker.close();broker=new ProbeBroker(config);},async close(){await broker.close();await fs.rm(root,{recursive:true,force:true});}};
}
test('AP08 already aborted signal starts no child',async()=>{const c=new AbortController();c.abort();let starts=0;const r=await processRun('/bin/sleep',['1'],{signal:c.signal,onSpawn:()=>starts++});assert.equal(starts,0);assert.equal(r.spawned,false);assert.equal(r.stopReason,'cancelled');assert.equal(r.terminationConfirmed,true);});
test('actual stubborn process group is cancelled, escalated and confirmed absent',async t=>{
 const c=new AbortController();let ready;const started=new Promise(r=>ready=r);const begin=Date.now();
 const work=processRun(process.execPath,[new URL('./fixtures/fake-codex.mjs',import.meta.url).pathname,'--fixture=stubborn','--descendant'],{signal:c.signal,timeoutMs:5000,terminateGraceMs:75,onRecord:e=>{if(e.ready)ready();}});
 await started;c.abort();const r=await work;assert.equal(r.stopReason,'cancelled');assert.ok(r.signals.some(x=>x.signal==='SIGKILL'));assert.equal(r.terminationConfirmed,true);assert.deepEqual(liveGroupMembers(r.pgid),[]);assert.ok(Date.now()-begin<2200);t.diagnostic(JSON.stringify({kind:'actual_subprocess_group',elapsedMs:Date.now()-begin,stopReason:r.stopReason,signals:r.signals.map(x=>x.signal),terminationConfirmed:r.terminationConfirmed,residualPids:r.residualPids}));
});
test('AP06 stalled verification has its own deadline and durable outcome',async()=>{const f=await fixture({verify:()=>new Promise(()=>{})});try{const t=Date.now(),r=await f.accept('联调开始','v');assert.equal(r.status,'verification_timeout');assert.ok(Date.now()-t<500);assert.equal(f.calls,0);assert.equal(f.sent.length,0);assert.equal(f.broker.db.prepare("SELECT status FROM intakes WHERE id='v'").get().status,'verification_timeout');}finally{await f.close();}});
test('stop during verification ignores a late valid identity',async()=>{let release;const f=await fixture({verify:()=>new Promise(r=>release=r)});try{const pending=f.accept('联调开始','v');await delay(5);const stopped=await f.broker.stop();assert.equal(stopped.confirmed,true);release(f.events.get('v'));assert.equal((await pending).status,'verification_cancelled');assert.equal(f.sent.length,0);}finally{await f.close();}});
test('AP05 unresponsive send times out to unknown and never repeats',async()=>{let attempts=0;const f=await fixture({reply:()=>{attempts++;return new Promise(()=>{})}});try{await f.accept('联调开始','s');await f.broker.queue;assert.equal(f.broker.db.prepare("SELECT status FROM messages WHERE id='s'").get().status,'reply_unknown');await f.restart();assert.equal((await f.accept('联调开始','s')).status,'duplicate');assert.equal(attempts,1);}finally{await f.close();}});
test('AP09 readback timeout preserves sent receipt',async()=>{const f=await fixture({readReply:()=>new Promise(()=>{})});try{await f.accept('联调开始','s');await f.broker.queue;const row=f.broker.db.prepare("SELECT * FROM messages WHERE id='s'").get();assert.equal(row.status,'sent');assert.ok(row.reply_id);assert.equal((await f.broker.stop()).confirmed,true);}finally{await f.close();}});
test('stop cancels an in-flight send; late send result cannot mark readback',async()=>{let release;const f=await fixture({sendTimeoutMs:1000,reply:()=>new Promise(r=>release=r)});try{await f.accept('联调开始','s');await delay(5);await f.broker.stop();release({messageId:'late',chatId:'c'});await delay(5);assert.equal(f.broker.db.prepare("SELECT status FROM messages WHERE id='s'").get().status,'reply_unknown');}finally{await f.close();}});
test('AP07 crash-queued becomes explicit interrupted_unstarted on restart',async()=>{const f=await fixture();try{await f.broker.close();const d=new DatabaseSync(f.config.file);d.prepare("INSERT INTO messages VALUES('q','session','queued','{}',NULL,NULL)").run();d.close();await f.restart();assert.equal(f.broker.db.prepare("SELECT status FROM messages WHERE id='q'").get().status,'interrupted_unstarted');assert.equal((await f.accept('计算合成样本','q')).storedStatus,'interrupted_unstarted');assert.equal(f.calls,0);}finally{await f.close();}});
test('second broker cannot mutate the first owner state',async()=>{const f=await fixture();try{assert.throws(()=>new ProbeBroker(f.config),/BROKER_ALREADY_OWNED/);await f.accept('联调开始','s');await f.broker.queue;assert.equal(f.sent.length,1);}finally{await f.close();}});
test('AP04 stop reaches and terminates actual process worker',async t=>{
 let ready;const started=new Promise(r=>ready=r);let receipt;
 const f=await fixture({execute:async x=>{receipt=await processRun(process.execPath,[new URL('./fixtures/fake-codex.mjs',import.meta.url).pathname,'--fixture=stubborn'],{signal:x.signal,timeoutMs:5000,onRecord:e=>{if(e.ready)ready();}});throw Error('cancelled');}});
 try{await f.accept('联调开始','s');await f.broker.queue;await f.accept('计算合成样本','w');await started;const r=await f.broker.stop();assert.equal(r.confirmed,true);assert.ok(r.elapsedMs<2500);assert.equal(receipt.stopReason,'cancelled');assert.equal(receipt.terminationConfirmed,true);assert.equal(f.sent.length,1);assert.deepEqual(liveGroupMembers(receipt.pgid),[]);t.diagnostic(JSON.stringify({kind:'broker_to_process_stop',...r,processTerminationConfirmed:receipt.terminationConfirmed}));}finally{await f.close();}
});
